add_filter( 'woocommerce_sale_flash', 'perfectpixel_discount_percentage_badge', 15, 3 );

function perfectpixel_discount_percentage_badge( $html, $post, $product ) {
	if ( ! $product || ( is_product() && get_queried_object_id() === $product->get_id() ) ) {
		return $html; // Loops only.
	}
	$max = 0;
	$ids = $product->is_type( 'variable' ) ? $product->get_children() : array( $product->get_id() );
	foreach ( $ids as $id ) {
		$item = $id === $product->get_id() ? $product : wc_get_product( $id );
		if ( $item && $item->is_on_sale() && (float) $item->get_regular_price() > 0 ) {
			$max = max( $max, 100 - (float) $item->get_sale_price() / (float) $item->get_regular_price() * 100 );
		}
	}
	if ( $max < 1 ) {
		return $html;
	}
	$prefix = $product->is_type( 'variable' ) ? esc_html( '{{percent_badge_upto}}' ) . ' ' : '';
	return '<span class="onsale">' . $prefix . '-' . (int) round( $max ) . '%</span>';
}
